xpath.script:
/** @odoo-module **/

// =========================================================================
// THREADORA GARMENTS - LIGHT/DARK MODE & 3D INTERACTIVE CONTROLLER
// =========================================================================

document.addEventListener('DOMContentLoaded', () => {
    initThemeMode();
    initStickyHeader();
    initStatsCounter();
    initFAQAccordion();
    init3DHeroCanvas();
    initProductSwatches();
});

/* 1. LIGHT / DARK MODE ENGINE */
function initThemeMode() {
    const savedTheme = localStorage.getItem('threadora_theme');
    const systemPrefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    const initialTheme = savedTheme || (systemPrefersDark ? 'dark' : 'light');

    setTheme(initialTheme);

    const toggleButtons = document.querySelectorAll('.js_theme_toggle_btn');
    toggleButtons.forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
            const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
            setTheme(newTheme);
            localStorage.setItem('threadora_theme', newTheme);
        });
    });

    if (window.matchMedia) {
        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', e => {
            if (!localStorage.getItem('threadora_theme')) {
                setTheme(e.matches ? 'dark' : 'light');
            }
        });
    }
}

function setTheme(theme) {
    document.documentElement.setAttribute('data-theme', theme);
    document.body.setAttribute('data-theme', theme);

    const toggleText = document.querySelectorAll('.js_theme_mode_label');
    const toggleIcon = document.querySelectorAll('.js_theme_mode_icon');

    toggleText.forEach(el => {
        el.textContent = theme === 'dark' ? 'LIGHT' : 'DARK';
    });
    toggleIcon.forEach(el => {
        el.className = theme === 'dark' ? 'fa fa-sun-o js_theme_mode_icon' : 'fa fa-moon-o js_theme_mode_icon';
    });
}

/* 2. STICKY GLASSMORPHIC HEADER */
function initStickyHeader() {
    const header = document.querySelector('.o_garment_header');
    if (!header) return;

    window.addEventListener('scroll', () => {
        if (window.scrollY > 40) {
            header.classList.add('scrolled');
        } else {
            header.classList.remove('scrolled');
        }
    }, { passive: true });
}

/* 3. STATS NUMBERS COUNTER ANIMATION */
function initStatsCounter() {
    const statsSection = document.querySelector('.s_garment_stats');
    if (!statsSection) return;

    let hasRun = false;
    const observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting && !hasRun) {
            hasRun = true;
            document.querySelectorAll('.js_stat_number').forEach(counter => {
                const target = parseInt(counter.getAttribute('data-target') || '0', 10);
                let count = 0;
                const speed = 2000 / (target || 1);
                const timer = setInterval(() => {
                    count += Math.ceil(target / 40);
                    if (count >= target) {
                        counter.textContent = target;
                        clearInterval(timer);
                    } else {
                        counter.textContent = count;
                    }
                }, 30);
            });
        }
    }, { threshold: 0.2 });

    observer.observe(statsSection);
}

/* 4. FAQ ACCORDION CONTROLLER */
function initFAQAccordion() {
    const faqItems = document.querySelectorAll('.s_garment_faq_item');
    faqItems.forEach(item => {
        const header = item.querySelector('.s_garment_faq_header');
        const body = item.querySelector('.s_garment_faq_body');
        if (!header || !body) return;

        header.addEventListener('click', () => {
            const isOpen = body.style.display === 'block';
            document.querySelectorAll('.s_garment_faq_body').forEach(b => b.style.display = 'none');
            document.querySelectorAll('.s_garment_faq_header .fa').forEach(i => {
                i.classList.remove('fa-minus');
                i.classList.add('fa-plus');
            });

            if (!isOpen) {
                body.style.display = 'block';
                const icon = header.querySelector('.fa');
                if (icon) {
                    icon.classList.remove('fa-plus');
                    icon.classList.add('fa-minus');
                }
            }
        });
    });
}

/* 5. PRODUCT COLOR SWATCH SWITCHER */
function initProductSwatches() {
    document.querySelectorAll('.s_garment_product_card').forEach(card => {
        const swatches = card.querySelectorAll('.s_garment_swatch');
        const img = card.querySelector('.s_garment_prod_img');
        swatches.forEach(swatch => {
            swatch.addEventListener('click', (e) => {
                e.preventDefault();
                swatches.forEach(s => s.classList.remove('active'));
                swatch.classList.add('active');
                const newImg = swatch.getAttribute('data-img');
                if (newImg && img) {
                    img.src = newImg;
                }
            });
        });
    });
}

/* 6. 3D WEBGL HERO CANVAS CONTROLLER */
function init3DHeroCanvas() {
    const canvas = document.getElementById('threadoraHeroCanvas');
    if (!canvas) return;

    // Check WebGL and reduced-motion support
    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (prefersReducedMotion) {
        showFallback();
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) {
        showFallback();
        return;
    }

    function showFallback() {
        const fallback = document.querySelector('.s_garment_3d_fallback');
        if (fallback) fallback.style.display = 'flex';
        if (canvas) canvas.style.display = 'none';
    }

    let width = canvas.width = canvas.parentElement.clientWidth || 500;
    let height = canvas.height = canvas.parentElement.clientHeight || 500;

    let mouseX = 0;
    let mouseY = 0;
    let targetRotationX = 0;
    let targetRotationY = 0;
    let currentRotationX = 0;
    let currentRotationY = 0;
    let isVisible = true;

    // IntersectionObserver to pause rendering when offscreen
    const observer = new IntersectionObserver((entries) => {
        isVisible = entries[0].isIntersecting;
    }, { threshold: 0.05 });
    observer.observe(canvas);

    window.addEventListener('resize', () => {
        if (!canvas.parentElement) return;
        width = canvas.width = canvas.parentElement.clientWidth;
        height = canvas.height = canvas.parentElement.clientHeight;
    });

    canvas.parentElement.addEventListener('mousemove', (e) => {
        const rect = canvas.getBoundingClientRect();
        mouseX = (e.clientX - rect.left) / width - 0.5;
        mouseY = (e.clientY - rect.top) / height - 0.5;
        targetRotationY = mouseX * 0.8;
        targetRotationX = -mouseY * 0.4;
    });

    canvas.parentElement.addEventListener('mouseleave', () => {
        targetRotationX = 0;
        targetRotationY = 0;
    });

    // Procedural Floating Textile / Fashion 3D Elements
    const particles = [];
    const numParticles = 48;
    for (let i = 0; i < numParticles; i++) {
        particles.push({
            x: (Math.random() - 0.5) * 380,
            y: (Math.random() - 0.5) * 380,
            z: (Math.random() - 0.5) * 380,
            size: Math.random() * 3 + 1.5,
            speedY: Math.random() * 0.4 + 0.1,
            color: i % 2 === 0 ? 'rgba(197, 168, 128, 0.7)' : 'rgba(212, 175, 55, 0.5)'
        });
    }

    let angle = 0;

    function render() {
        if (isVisible) {
            ctx.clearRect(0, 0, width, height);

            currentRotationX += (targetRotationX - currentRotationX) * 0.05;
            currentRotationY += (targetRotationY - currentRotationY) * 0.05;

            const cx = width / 2;
            const cy = height / 2;

            angle += 0.008;

            // Draw Floating Textile Particles in 3D Perspective
            particles.forEach(p => {
                p.y -= p.speedY;
                if (p.y < -200) p.y = 200;

                const rotX = p.x * Math.cos(angle + currentRotationY) - p.z * Math.sin(angle + currentRotationY);
                const rotZ = p.x * Math.sin(angle + currentRotationY) + p.z * Math.cos(angle + currentRotationY);

                const perspective = 400 / (400 + rotZ + 200);
                const px = cx + rotX * perspective;
                const py = cy + (p.y + currentRotationX * 80) * perspective;

                if (perspective > 0) {
                    ctx.beginPath();
                    ctx.arc(px, py, p.size * perspective, 0, Math.PI * 2);
                    ctx.fillStyle = p.color;
                    ctx.fill();
                }
            });

            // Draw Luxury 3D Garment Geometric Silhouette
            ctx.save();
            ctx.translate(cx, cy);
            ctx.rotate(currentRotationY + Math.sin(angle * 0.5) * 0.08);

            // Outer Orbit Ring
            ctx.beginPath();
            ctx.ellipse(0, 0, 180, 70, angle * 0.3, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(197, 168, 128, 0.25)';
            ctx.lineWidth = 1.5;
            ctx.stroke();

            // Inner Ring
            ctx.beginPath();
            ctx.ellipse(0, 0, 130, 50, -angle * 0.4, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(212, 175, 55, 0.35)';
            ctx.lineWidth = 1;
            ctx.stroke();

            // Center Garment Mannequin Contours
            ctx.beginPath();
            // Shoulders & Torso Outline
            ctx.moveTo(0, -120);
            ctx.quadraticCurveTo(60, -110, 80, -70);
            ctx.quadraticCurveTo(45, 10, 55, 110);
            ctx.lineTo(-55, 110);
            ctx.quadraticCurveTo(-45, 10, -80, -70);
            ctx.quadraticCurveTo(-60, -110, 0, -120);
            ctx.closePath();

            const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
            ctx.fillStyle = isDark ? 'rgba(255, 255, 255, 0.04)' : 'rgba(17, 17, 17, 0.03)';
            ctx.fill();
            ctx.strokeStyle = isDark ? 'rgba(255, 255, 255, 0.7)' : 'rgba(17, 17, 17, 0.8)';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Textile Weave Lines
            for (let j = -80; j <= 80; j += 25) {
                ctx.beginPath();
                ctx.moveTo(-50, j);
                ctx.lineTo(50, j);
                ctx.strokeStyle = 'rgba(197, 168, 128, 0.4)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }

        requestAnimationFrame(render);
    }

    render();
}
